@page{size:1200px 1600px;margin:0}
*{box-sizing:border-box}
body{margin:0;font-family:"Apple SD Gothic Neo",sans-serif;color:#222;font-size:21px;line-height:1.5}
.pg{width:1200px;height:1600px;padding:36px 44px;overflow:hidden;page-break-after:always;position:relative}
h1{font-size:30px;margin:0 0 4px;color:#7a1f2e} h1 small{font-size:17px;color:#888;font-weight:400;margin-left:10px}
.sub{color:#666;font-size:16px;margin-bottom:14px}
.mode{position:absolute;top:36px;right:44px;font-size:16px;font-weight:800;padding:3px 12px;border-radius:99px;color:#fff}
.quiz .mode{background:#c0392b} .ans .mode{background:#2e75b6}
h2{font-size:22px;margin:18px 0 8px;color:#5a1620;border-left:6px solid #7a1f2e;padding-left:10px}
h2 small{font-size:15px;color:#888;font-weight:400;margin-left:8px}
table{border-collapse:collapse;width:100%;table-layout:fixed;margin-bottom:6px}
th,td{border:1px solid #999;padding:8px 11px;vertical-align:top}
th{background:#f3dde1;color:#5a1620;text-align:center;font-size:19px}
td.k{background:#faf2f3;text-align:center;font-weight:700;vertical-align:middle}
ul{margin:0;padding-left:22px} li{margin:3px 0}
.star{color:#1f4e9c;font-weight:700}
.b{display:inline-block;min-width:64px;padding:0 6px;border-bottom:2px solid #c0392b;text-align:center;color:transparent;background:#fff5cc;border-radius:3px 3px 0 0}
.b.w{min-width:130px} .b.xw{min-width:220px}
.ans .b{color:#c0392b;font-weight:700;background:#fff}
.foot{margin-top:12px;font-size:16px;color:#666;border-top:1px dashed #bbb;padding-top:8px}
.hl{padding:0 4px;border-radius:3px;font-weight:700} .hl1{background:#ffe08a} .hl2{background:#c9e7ff} .hl3{background:#d6f5c9}

body{font-size:20px;line-height:1.45}
h2{margin:12px 0 4px;font-size:21px;padding-left:9px;border-left-width:5px}
ul.it{margin:0;padding-left:0;list-style:none}
ul.it li{margin:0 0 5px;padding:4px 8px 4px 12px;border-bottom:1px dashed #ddd;position:relative}
.tg{display:inline-block;font-size:13px;color:#fff;background:#7a1f2e;border-radius:4px;padding:0 6px;margin-right:6px;vertical-align:2px;white-space:nowrap}
.tg.s3{background:#c0392b} .tg.s2{background:#b7651c} .tg.s1{background:#7a7a7a}
.b{position:relative;min-width:54px} .b sup{position:absolute;left:2px;top:-4px;font-size:12px;color:#c0392b;font-weight:700}
.key{position:absolute;left:44px;right:44px;bottom:30px;border-top:2px solid #7a1f2e;padding-top:8px;font-size:15.5px;line-height:1.5;color:#333;column-count:4;column-gap:18px}
.key .kt{font-weight:800;color:#7a1f2e;font-size:15px;column-span:all;margin-bottom:3px}
.key span{display:block;break-inside:avoid} .key b{color:#c0392b;margin-right:5px}
.legend{font-size:15px;color:#666;margin:-6px 0 8px}
.legend .tg{vertical-align:0}

