.key .kt{font-weight:800;color:#7a1f2e;font-size:16px;column-span:all;margin-bottom:4px}
.key span{display:block;break-inside:avoid} .key b{color:#c0392b;margin-right:6px}
.key i{font-style:normal;color:#c0392b;font-weight:700}
.pg{padding-bottom:40px}

